 1883;  // Puerto MQTT por defecto\nconst char* mqtt_username = "ABC";\nconst char* mqtt_password = "ABC123";\n\nWiFiClient espClient;\nPubSubClient client(espClient);\n\nvoid setup() {\n  Serial.begin(115200);\n  WiFi.begin(ssid, password);\n  client.setCallback(callback);\n  while (WiFi.status() != WL_CONNECTED) {\n    delay(1000);\n    Serial.println("Conectando a WiFi...");\n  }\n\n  Serial.println("Conectado a WiFi");\n  client.setServer(mqtt_server, mqtt_port);\n}\n\nvoid loop() {\n  if (!client.connected()) {\n    reconnect();\n  }\n  client.loop();\n\n  // Generar valores aleatorios para cada laboratorio: VOC, presencia humana, temperatura y humedad\n  for (int lab = 1; lab <= 3; lab++) {\n    int voc = random(60, 80);\n    int presence = random(0, 3); // Asumiendo que la presencia se representa como un booleano (0 para sin presencia, 1 para presencia)\n    bool acState = false; // Estado inicial del A/C apagado\n    float temperature = random(18, 30); // Asumiendo que la temperatura est\xe1 en Celsius\n    int humidity = random(30, 70); // Asumiendo que la humedad es un porcentaje\n    bool fire = false;\n\n    // Comprobar si la temperatura es superior a 25 y hay presencia humana\n    if (temperature > 25 && presence) {\n      acState = true; // Encender el A/C\n    }\n\n    // Construir el payload\n    String payload = "{\\"lab\\":" + String(lab) + ",\\"voc\\":" + String(voc) + ",\\"presence\\":" + String(presence) + ",\\"acState\\":" + String(acState) + ",\\"temperature\\":" + String(temperature) + ",\\"humidity\\":" + String(humidity) +",\\"fire\\":" + String(fire) + "}";\n\n    // Publicar el payload para el laboratorio actual\n    client.publish(("Lab" + String(lab) + "/data").c_str(), payload.c_str());\n  }\n\n  delay(10000); // Esperar 10 segundos antes de enviar nuevos datos\n}\n\nvoid reconnect() {\n  while (!client.connected()) {\n    Serial.println("Intentando conexi\xf3n MQTT...");\n    if (client.connect("ESP32Client", mqtt_username, mqtt_password)) {\n      Serial.println("Conectado");\n      // Suscribirse a temas si es necesario\n       client.subscribe("rpi/data");\n    } else {\n      Serial.print("Fallo, rc=");\n      Serial.print(client.state());\n      Serial.println(" intent\xe1ndolo de nuevo en 5 segundos");\n      delay(5000);\n    }\n  }\n}\n\nvoid callback(char* topic, byte* payload, unsigned int length) {\n    Serial.print("Mensaje recibido en el tema: ");\n    Serial.println(topic);\n\n    Serial.print("Mensaje:");\n    for (int i = 0; i < length; i++) {\n        Serial.print((char)payload[i]);\n    }\n    Serial.println();\n}\n')),(0,i.yg)("h3",{id:"habilitar-el-broker-mqtt"},"Habilitar el Broker MQTT"),(0,i.yg)("ul",null,(0,i.yg)("li",{parentName:"ul"},(0,i.yg)("p",{parentName:"li"},"Navega a ",(0,i.yg)("strong",{parentName:"p"},"Settings")," -> ",(0,i.yg)("strong",{parentName:"p"},"Data Collectors"),".")),(0,i.yg)("li",{parentName:"ul"},(0,i.yg)("p",{parentName:"li"},"Haz clic en el bot\xf3n ",(0,i.yg)("strong",{parentName:"p"},"ADD CONNECTOR")," para agregar un nuevo recolector."))),(0,i.yg)("center",null,(0,i.yg)("img",{width:1e3,src:"https://files.seeedstudio.com/wiki/reTerminalDM/JEDI/mqtt1.PNG"})),(0,i.yg)("ul",null,(0,i.yg)("li",{parentName:"ul"},(0,i.yg)("p",{parentName:"li"},'Selecciona "MQTT Broker" como el Tipo de Recolector.')),(0,i.yg)("li",{parentName:"ul"},(0,i.yg)("p",{parentName:"li"},"Opciones de Configuraci\xf3n Avanzada:"),(0,i.yg)("ul",{parentName:"li"},(0,i.yg)("li",{parentName:"ul"},"Listen IP: La direcci\xf3n IP en la que escucha el broker MQTT. En este caso, la IP de JEDI.")))),(0,i.yg)("center",null,(0,i.yg)("img",{width:1e3,src:"https://files.seeedstudio.com/wiki/reTerminalDM/JEDI/mqtt2.PNG"})),(0,i.yg)("admonition",{type:"note"},(0,i.yg)("p",{parentName:"admonition"},(0,i.yg)("strong",{parentName:"p"},"Username/Password"),": Habilita esta opci\xf3n y configura el nombre de usuario y la contrase\xf1a para la autenticaci\xf3n del cliente. Los clientes deber\xe1n